select jsonb_array_length(produtos_loja->'itens') as produtos
  from public.postos where id = 1786715345306;

select it->>'n' as produto, it->>'g' as grupo, (it->>'v')::numeric as faturamento
  from public.postos p
  cross join lateral jsonb_array_elements(p.produtos_loja->'itens') it
 where p.id = 1786715345306
 order by (it->>'v')::numeric desc
 limit 5;
